/**
 * У воркера pdf.js нет файла типов — только сам модуль.
 *
 * Объявление нужно ради одной строки в lib/hiring/pdf.ts: воркер там
 * импортируется, чтобы попасть в сборку, а не ради его API. Поэтому тип
 * умышленно пустой: описывать здесь чужой обработчик значило бы завести
 * вторую, расходящуюся копию его сигнатуры.
 */
declare module "pdfjs-dist/legacy/build/pdf.worker.mjs";
